#include <vector>

int sum(const std::vector<int>& v) {
    int total = 0;
    for (auto it = v.begin(); it != v.end(); ++it)   // [begin, end): end never read.
        total += *it;
    return total;                                   // empty v: zero steps.
}

void remove_odds(std::vector<int>& v) {
    for (auto it = v.begin(); it != v.end();) {
        if (*it % 2 != 0)
            it = v.erase(it);          // erase returns the next valid iterator.
        else
            ++it;                      // only advance when nothing was erased.
    }
}
// Simpler in C++20: std::erase_if(v, [](int x) { return x % 2 != 0; });
```

| Operation on vector | Invalidates |
|---|---|
| `push_back` with reallocation. | all iterators and references. |
| `push_back` without reallocation. | only end(). |
| `erase(it)`. | it and everything after it. |
| reading, `[]`, `at`. | nothing. |

